function i(n){const t=n.trim();if(t.length>24||!/^\d+(?:\.\d{1,2})?$/.test(t))throw new Error("金额须为非负数，最多两位小数");const[e="",o=""]=t.split("."),r=BigInt(e)*100n+BigInt(o.padEnd(2,"0"));if(r>BigInt(Number.MAX_SAFE_INTEGER))throw new Error("金额超出可精确处理的范围");return Number(r)}function s(n){if(!Number.isSafeInteger(n)||n<0)throw new Error("金额数据无效");const t=BigInt(n);return`${t/100n}.${String(t%100n).padStart(2,"0")}`}export{s as c,i as m};
